  Lemma land3_range : forall z, (0 <= z)%Z -> (0 <= Z.land z 3 <= 3)%Z.
  Proof.
    intros z Hz. replace (Z.land z 3) with (z mod 4)%Z by (symmetry; apply (Z.land_ones z 2); lia).
    pose proof (Z.mod_pos_bound z 4 ltac:(lia)). lia.
  Qed.

