  Lemma seg_T1zero : forall s msF mo regs mem (cfgz : Z) (PL CP : word) (c : byte) K,
    regs118 regs (Z_to_bv 64 0) PL (Z_to_bv 64 cfgz) CP -> (0 <= cfgz < 2 ^ 62)%Z ->
    (cfgz <> 0%Z -> rdn RSEGS mem CP 1 = Some [c]) -> (bv_unsigned CP + 1 < 2 ^ 64)%Z ->
    stk_ok RSEGS mem sp 80 -> aro_none mem -> arelro_none mem -> latch_ok mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xa3058) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        loop_base regs' (Z_to_bv 64 0) (Z_to_bv 64 0x65bae0) (Z_to_bv 64 0) -> getr regs' 21 = Z_to_bv 64 (calls_of cfgz c) ->
        getr regs' 19 = CP -> keep4 regs regs' ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa2fe8) mem rom -> as_AKREL H s (mkCfg msF mo) ->
