  Lemma seg_T2 : forall s msF mo regs mem (N PL cfg CP r : word) K,
    regs118 regs N PL cfg CP -> getr regs 21 = r ->
    stk_ok RSEGS mem sp 80 -> aro_none mem -> arelro_none mem -> latch_ok mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0x73278) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        regs118 regs' N PL cfg CP -> getr regs' 21 = r -> getr regs' 1 = Z_to_bv 64 0xa3004 -> getr regs' 10 = N ->
        keep4 regs regs' ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa2ffc) mem rom -> as_AKREL H s (mkCfg msF mo) ->
